-- =====================================================================
--  LÅTSNURRAN – 327 nya svenska låtar ur artistkatalogerna
--
--  0071 läkte låtar som redan fanns i potten. De här fanns inte alls: de
--  låg i artisternas kataloger men hade aldrig kommit med, eftersom potten
--  byggdes ur Sverigetopplistans veckoarkiv och en låt som aldrig nådde
--  listan inte finns där.
--
--  URVALET. Katalogerna gav 1 865 låtar som saknades i potten. Att lägga in
--  alla hade varit fel – ett rapalbum är mest spår som ingen känner igen,
--  och en pott full av dem gör spelet sämre, inte större. Fyra krav:
--
--    1. TVÅ KÄLLOR OM ÅRET. iTunes och Deezer måste säga samma utgivningsår.
--       1 300 låtar gick att slå upp hos Deezer, 1 155 var eniga om året.
--       Samma regel som gällde när potten byggdes.
--
--    2. TILLRÄCKLIGT KÄND. Deezer-rank >= 50 000. Tröskeln är kalibrerad mot
--       potten själv, inte gissad: ett stickprov på 219 svenska låtar som
--       redan ligger där har median-rank ~100 000 och 33 % under 50 000.
--       Kravet motsvarar alltså pottens egen 33:e percentil – nya låtar blir
--       inte mindre kända än den tredjedel som redan är minst känd.
--       409 låtar klarade det.
--
--    3. INTE RANK EXAKT 100000. Det är Deezers STANDARDVÄRDE när ingen
--       popularitetsdata finns, inte en mätning – 93 kandidater hade det på
--       pricken. De bar dessutom nästan allt skräp: katalogerna för vanliga
--       namn (Owen, Dizzy, Denz, Adel, Yasin) innehåller låtar av UTLÄNDSKA
--       NAMNAR, och de kom in just här. 78 föll bort.
--
--    4. GENRE SOM HÖR TILL ETT SPELLÄGE. Tog de sista fyra: Malayalam,
--       Afrobeats, Latin urban, Modern Dancehall.
--
--  I 0071 spelade namnarna ingen roll – varje katalogträff måste matcha en
--  redan vettad pott-rad, så fel artist gav bara noll träffar. För NYA
--  låtar finns ingen sådan spärr, och då krävs de här filtren i stället.
--
--  Kvar: 327 låtar, 2012–2026.
--
--  De kommer in FÄRDIGT SPELBARA – preview-URL och Apples spår-id följer
--  med ur katalogen, preview_source = 'catalog'. Ingen av dem behöver
--  slås upp vid speltillfället, och ingen kan bli "ohittbar" senare.
--
--  GENREN MÅSTE ÖVERSÄTTAS. `track_pool.genre` har hittills innehållit
--  Deezers råa genresträng, och `_genre_key` känner bara igen den. iTunes
--  säger "Hiphop/Rap" där Deezer säger "Rap/Hip Hop" – utan den här
--  utvidgningen hade _genre_key gett NULL och alla 327 låtarna varit
--  OSYNLIGA i hiphop-läget trots att de ligger i potten. Funktionen känner
--  nu igen båda vokabulärerna; kolumnen betyder "rågenre från den källa
--  raden kom ifrån".
--
--  OBS: _genre_key ingår i indexet track_pool_genre_idx. Att ändra en
--  IMMUTABLE funktion som ett index bygger på gör inte om indexet – därför
--  reindexeras det uttryckligen nedan. Utan det hade de nya raderna kunnat
--  få fel plats i indexet. (Inga BEFINTLIGA mappningar ändras: 'Pop',
--  'Dance', 'Rock' och 'Reggae' betyder samma sak i båda vokabulärerna.)
--
--  Artister: 23, 24 SJU, 24K, A36, ADAAM, Adel, Aden, Aden x Asme, Ant Wan, Asme, Baby Gang, Ballinciaga, Bausa, Blizzy, D1MA, Dani M, De Vet Du, Delara, Denz, Deso, Dizzy, Dree Low m.fl. (72 totalt)
--
--  Additiv + idempotent (on conflict do nothing mot dedup-indexet).
--  Kör efter 0072.
-- =====================================================================

-- --- 1. _genre_key förstår även iTunes vokabulär ----------------------
create or replace function public._genre_key(p_genre text)
returns text language sql immutable as $function$
  select case
    when p_genre is null then null
    -- Deezer (som förut)
    when p_genre = 'Pop' then 'pop'
    when p_genre in ('Rock', 'Alternativmusik', 'Metal') then 'rock'
    when p_genre = 'Rap/Hip Hop' then 'hiphop'
    when p_genre in ('Dance', 'Electro', 'Disco') then 'dance'
    when p_genre in ('R&B', 'Soul & Funk') then 'rnb'
    -- iTunes
    when p_genre in ('Hiphop/Rap', 'Hiphop', 'Rap', 'Alternative Rap',
                     'Gangsta Rap', 'Undergroundrap', 'Hardcore Rap',
                     'Hip-Hop/Rap') then 'hiphop'
    when p_genre in ('Alternativt', 'Alternative', 'Hårdrock', 'Hard Rock',
                     'Punk') then 'rock'
    when p_genre in ('Elektroniskt', 'Electronic', 'House', 'Techno') then 'dance'
    when p_genre in ('R&B/Soul', 'Soul') then 'rnb'
    else null
  end
$function$;

reindex index public.track_pool_genre_idx;

